export interface University {
  id: string;
  slug: string;
  name_ar: string;
  name_fr: string;
  city: string;
  city_ar: string;
  description: string;
  website?: string | null;
  logo_url?: string | null;
  faculties_count?: number;
  created_date?: string;
  updated_date?: string;
  created_by_id?: string;
  is_sample?: boolean;
}

export interface Faculty {
  id: string;
  university_id: string;
  slug: string;
  name_ar: string;
  name_fr: string;
  type?: 'FSJES' | 'FLSH' | 'FS' | 'FST' | 'FP' | 'ENCG' | 'ENSA' | 'EST' | 'Autre';
  city?: string;
  description?: string;
  created_date?: string;
  updated_date?: string;
  created_by_id?: string;
  is_sample?: boolean;
}

export interface Program {
  id: string;
  university_id: string;
  faculty_id?: string;
  slug: string;
  name_ar: string;
  name_fr: string;
  cycle?: 'Licence Fondamentale' | 'Licence Professionnelle' | 'Master' | 'DUT';
  description?: string;
  created_date?: string;
  updated_date?: string;
  created_by_id?: string;
  is_sample?: boolean;
}

export interface Subject {
  id: string;
  slug: string;
  name_ar: string;
  name_fr: string;
  semester?: string;
  program_slug?: string;
  created_date?: string;
  updated_date?: string;
  created_by_id?: string;
  is_sample?: boolean;
}

export interface Exam {
  id: string;
  slug: string;
  title: string;
  description?: string | null;
  university_id: string;
  faculty_id?: string | null;
  program_id?: string | null;
  subject_id?: string | null;
  semester: string;
  session: 'normale' | 'rattrapage' | 'autre';
  year: number;
  download_count: number;
  source_url?: string | null;
  file_name?: string | null;
  file_uri?: string | null;
  correction_type: 'officiel' | 'propose' | 'sans_corrige';
  has_correction: boolean;
  correction_notes?: string;
  verification_status: 'verified' | 'pending' | 'reported';
  last_verified_date: string;
  source_origin: string;
  language: 'ar' | 'fr' | 'ar_fr';
  seo_title?: string | null;
  seo_description?: string | null;
  tags?: string[];
  status?: string;
  created_date?: string;
  updated_date?: string;
  created_by_id?: string;
  is_sample?: boolean;
}

